insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (1,'{"number":1,"prompt":"Choose someone / something: There is _____ at reception asking to speak to the head teacher.","answer":"someone","explanation":"接待處來的是人，選 someone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (2,'{"number":2,"prompt":"Choose something / somewhere: I found _____ inside the envelope: a small silver key.","answer":"something","explanation":"信封裏的銀匙是物件，選 something。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (3,'{"number":3,"prompt":"Choose someone / somewhere: We need _____ to rest before we continue walking.","answer":"somewhere","explanation":"需要一個休息的地方，選 somewhere。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (4,'{"number":4,"prompt":"Choose everybody / everything: All twelve guests have arrived. _____ is here now.","answer":"Everybody","explanation":"十二位賓客全部到齊，指人用 everybody。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (5,'{"number":5,"prompt":"Choose nothing / nowhere: The cupboard is completely empty. There is _____ inside it.","answer":"nothing","explanation":"櫃子完全空了，裏面甚麼也沒有。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (6,'{"number":6,"prompt":"Complete with a some- word for an offer: Would you like _____ warm to drink?","answer":"something","explanation":"提供一杯熱飲時，something 很自然。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (7,'{"number":7,"prompt":"Complete with an any- person word in a neutral enquiry: Is _____ using this chair?","answer":"anyone / anybody","explanation":"中立地查問是否有人使用椅子。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (8,'{"number":8,"prompt":"Use an any- word to make the choice unrestricted: You may choose _____ you like from this tray.","answer":"anything","explanation":"讓對方任選托盤上的物件。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (9,'{"number":9,"prompt":"Use an any- person word: If _____ needs a lift, please tell me.","answer":"anyone / anybody","explanation":"if 引出尚未確定是否有人需要接送。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (10,'{"number":10,"prompt":"Use a some- person word in this request: Could _____ help me lift the lid?","answer":"someone / somebody","explanation":"請求有人幫忙時，some- 很自然。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (11,'{"number":11,"prompt":"Choose nobody / everybody: All twenty guests have taken their seats. _____ is seated.","answer":"Everybody","explanation":"二十位賓客全已入座。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (12,'{"number":12,"prompt":"Choose nothing / everything: The parcel is empty. There is _____ inside.","answer":"nothing","explanation":"包裹空了，裏面沒有東西。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (13,'{"number":13,"prompt":"Rewrite using anything: She said nothing during the interview.","answer":"She did not say anything during the interview.","explanation":"否定詞 not 後以 anything 表示沒有說任何事。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (14,'{"number":14,"prompt":"Rewrite using nobody: There was not anybody at the reception desk.","answer":"Nobody was at the reception desk.","explanation":"Nobody 自帶否定意思，動詞用肯定形式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (15,'{"number":15,"prompt":"Choose nowhere / everywhere: We checked every room, every cupboard and the garden. We looked _____.","answer":"everywhere","explanation":"所有相關地方都查過了。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (16,'{"number":16,"prompt":"Complete: Everybody _____ (know) the meeting time.","answer":"knows","explanation":"Everybody 作單數主語。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (17,'{"number":17,"prompt":"Choose has / have: Someone _____ taken my pencil.","answer":"has","explanation":"Someone 作單數主語，選 has。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (18,'{"number":18,"prompt":"Complete: Does anyone _____ (want) another copy?","answer":"want","explanation":"Does 後用動詞原形。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (19,'{"number":19,"prompt":"Choose is / are after they: If somebody is late, they _____ asked to wait outside.","answer":"are","explanation":"代詞 they 作主語，配 are。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (20,'{"number":20,"prompt":"Choose stand / stands for an instruction: Everybody _____ behind the line, please.","answer":"stand","explanation":"此處是祈使句，動詞用原形。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (21,'{"number":21,"prompt":"Put in the usual order: useful / something.","answer":"something useful","explanation":"形容詞通常放在這類不定代名詞後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (22,'{"number":22,"prompt":"Put in the usual order: quiet / somewhere / to study.","answer":"somewhere quiet to study","explanation":"地點詞後放形容詞，再接不定式表用途。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (23,'{"number":23,"prompt":"Choose all suitable relative words from who / that / what: I need someone _____ understands sign language.","answer":"who / that","explanation":"兩者均可引出修飾人的限制性關係子句；what 不可直接這樣接。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (24,'{"number":24,"prompt":"Complete with the normal preposition: She needs someone to speak _____. Use speak to a person.","answer":"to","explanation":"Speak to a person；介詞留在句尾也自然。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (25,'{"number":25,"prompt":"Choose planned / planning: Have you got anything _____ for Sunday? Refer to an activity already arranged.","answer":"planned","explanation":"指已安排的活動，用過去分詞 planned 修飾 anything。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (26,'{"number":26,"prompt":"Complete with else in the usual position: Is there anything _____ you need?","answer":"else","explanation":"Anything else 表示「其他東西」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (27,'{"number":27,"prompt":"Make possessive: someone else + umbrella.","answer":"someone else''s umbrella","explanation":"所有格的 ''s 放在 else 後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (28,'{"number":28,"prompt":"Choose everyone / every one: _____ of the tickets has a number.","answer":"Every one","explanation":"Every one of the tickets 指那組票逐張來看。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (29,'{"number":29,"prompt":"Choose anyone / any one: _____ of these keys might fit.","answer":"Any one","explanation":"Any one of these keys 指任意一條匙。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (30,'{"number":30,"prompt":"Choose nobody / none of them to refer explicitly to the named group: Three dancers were invited, but _____ could attend.","answer":"none of them","explanation":"明確回指受邀的三位舞者。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (31,'{"number":31,"prompt":"Choose somewhere / something: We should meet _____ quiet after the performance.","answer":"somewhere","explanation":"需要一個安靜的見面地點。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (32,'{"number":32,"prompt":"Use an any- place word: I cannot find the missing glove _____.","answer":"anywhere","explanation":"否定句中表示「任何地方都找不到」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (33,'{"number":33,"prompt":"Use a no- place word: Every hotel is full, so we have _____ to stay.","answer":"nowhere","explanation":"酒店都滿了，沒有地方住宿。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (34,'{"number":34,"prompt":"Use an every- place word: The wind scattered the leaves across the whole garden. Leaves were _____.","answer":"everywhere","explanation":"葉子散落在整個花園各處。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (35,'{"number":35,"prompt":"Complete with from / to: The postcard came _____ somewhere in northern Italy.","answer":"from","explanation":"來源地用 from somewhere。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (36,'{"number":36,"prompt":"Compare: Not everybody attended. / Nobody attended. Do they necessarily describe the same number of attendees?","answer":"No.","explanation":"Not everybody 只保證至少一位沒出席；nobody 表示一位也沒出席。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (37,'{"number":37,"prompt":"Compare: I didn''t travel everywhere. / I didn''t travel anywhere.","answer":"No.","explanation":"第一句表示未到過所有地方；第二句表示甚麼地方也沒去。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (38,'{"number":38,"prompt":"Compare: Someone has not replied. / No one has replied.","answer":"No.","explanation":"第一句至少有一位沒回覆；第二句表示一位也沒回覆。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (39,'{"number":39,"prompt":"Compare the instructions: Take anything you need. / Take everything you need.","answer":"No.","explanation":"Anything you need 讓人按需要選；everything you need 指把所需全部拿走。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (40,'{"number":40,"prompt":"Choose anyone / anything: There was nothing _____ could do to change the result. Refer to people attempting action.","answer":"anyone","explanation":"Nothing anyone could do 表示沒有任何人能採取有效行動。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (41,'{"number":41,"prompt":"Choose anything / nothing: The examination was _____ but easy; every section was difficult.","answer":"anything","explanation":"Anything but easy 表示一點也不容易。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (42,'{"number":42,"prompt":"Choose anything / nothing: We heard _____ but applause after the performance; there were no other sounds.","answer":"nothing","explanation":"Nothing but applause 表示除掌聲外沒有別的聲音。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (43,'{"number":43,"prompt":"Explain the exception: I remembered everything but my gloves.","answer":"I remembered all the items except my gloves.","explanation":"Everything but 排除手套，並非連手套也記得。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (44,'{"number":44,"prompt":"Complete with nowhere / anywhere: This limited edition is sold _____ but at the museum shop.","answer":"nowhere","explanation":"Nowhere but at the museum shop 表示只有該店出售。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (45,'{"number":45,"prompt":"What usual age range does twenty-something indicate?","answer":"In their twenties, approximately 20–29.","explanation":"Twenty-something 指二十多歲，沒有交代確切年齡。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (46,'{"number":46,"prompt":"Choose something / nothing: Buy the tickets now. I am afraid there will be _____ left later because every seat may sell out.","answer":"nothing","explanation":"全部座位可能售罄，之後恐怕一張也不剩。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (47,'{"number":47,"prompt":"Choose something / nothing: I hope to find _____ original for the exhibition; even one fresh idea would help.","answer":"something","explanation":"希望找到至少一個新點子；不表示已找到。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (48,'{"number":48,"prompt":"Choose something / nothing: The review says the film is ordinary and offers _____ special; it adds no new ideas at all.","answer":"nothing","explanation":"Nothing special 表示沒有特別之處。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (49,'{"number":49,"prompt":"Complete with they / it: Someone was standing behind the curtain. _____ stepped forward. It was our science teacher.","answer":"They","explanation":"指性別未明的那位人物，用單數 they。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (50,'{"number":50,"prompt":"Complete both gaps: This is not my bag; it must be someone _____. I will ask whether anyone _____ (know) its owner. Use the possessive of else.","answer":"It must be someone else''s. I will ask whether anyone knows its owner.","explanation":"Else 的所有格是 else''s；anyone 作單數主語，動詞用 knows。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (51,'{"number":51,"prompt":"Correct the spelling, using two words without a hyphen: Noone answered the door.","answer":"No one answered the door.","explanation":"普通標準拼法為分開兩字的 no one。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (52,'{"number":52,"prompt":"Complete with an any- thing word: We have never seen _____ like this before.","answer":"anything","explanation":"Never 的否定範圍內用 anything。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (53,'{"number":53,"prompt":"Rewrite using nothing: We did not find anything under the sofa.","answer":"We found nothing under the sofa.","explanation":"Nothing 自帶零數量意思。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (54,'{"number":54,"prompt":"Complete the tag: Nobody complained, _____?","answer":"did they?","explanation":"Nobody 是否定主語，附加問句用肯定形式及 they。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (55,'{"number":55,"prompt":"Complete with the correct preposition: I need something to write _____. A pencil would be ideal.","answer":"with","explanation":"鉛筆是書寫工具，something to write with。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (56,'{"number":56,"prompt":"Correct: This must be somebody''s else notebook.","answer":"This must be somebody else''s notebook.","explanation":"所有格加在 else 後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (57,'{"number":57,"prompt":"Complete the fixed phrase: A small boat suddenly appeared out of _____.","answer":"nowhere","explanation":"Out of nowhere 表示突然出現。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (58,'{"number":58,"prompt":"Compare: I didn''t follow something you explained. / I didn''t follow anything you explained.","answer":"No.","explanation":"第一句可能只是不明白其中一部分；第二句表示全部都沒聽懂。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (59,'{"number":59,"prompt":"What usual age range does forty-something indicate, and does it give an exact age?","answer":"In their forties, approximately 40–49; not an exact age.","explanation":"Forty-something 只給年齡段。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (60,'{"number":60,"prompt":"Explain the comparison: Nothing is more reassuring than a clear explanation. Is the speaker describing a reassuring object named Nothing?","answer":"No.","explanation":"Nothing is more reassuring than… 表示清楚解釋比任何其他事都令人安心。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (61,'{"number":61,"prompt":"Complete the tag: Nothing is broken, _____?","answer":"is it?","explanation":"Nothing 帶否定意思，附加問句用肯定形式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (62,'{"number":62,"prompt":"Complete with the correct preposition: I need something to write _____. A sheet of paper would help.","answer":"on","explanation":"紙張是書寫表面，something to write on。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (63,'{"number":63,"prompt":"Correct: It is someone elses'' responsibility.","answer":"It is someone else''s responsibility.","explanation":"Else 後加 ''s，無須再在 s 後加撇號。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (64,'{"number":64,"prompt":"Use the usual direct place-adverb pattern by removing the unnecessary to: We went to somewhere peaceful.","answer":"We went somewhere peaceful.","explanation":"Somewhere 是地點副詞，這裏不加 to。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (65,'{"number":65,"prompt":"Not everyone has submitted. Does this sentence guarantee that at least one person has submitted?","answer":"No.","explanation":"只保證至少一位沒交；不保證其他人已交。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (66,'{"number":66,"prompt":"Explain why -s is possible here without making everythings correct: The club attracts many thirty-somethings.","answer":"Thirty-somethings is a countable noun meaning people in their thirties.","explanation":"這種特殊名詞可用複數；普通代名詞 everything 不加 -s。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (67,'{"number":67,"prompt":"Rewrite using nowhere and better, preserving the claim that no place is better for the activity: No place is better than this beach for watching the sunset.","answer":"Nowhere is better than this beach for watching the sunset.","explanation":"否定地點詞置句首，保留「沒有更好地方」的比較。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (68,'{"number":68,"prompt":"Replace someone with the equivalent -body form: Someone has left an umbrella here.","answer":"Somebody has left an umbrella here.","explanation":"Somebody 與 someone 在這裏同義。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (69,'{"number":69,"prompt":"Use a some- place word: I would like to go _____ peaceful this weekend.","answer":"somewhere","explanation":"想去一個安靜地方，地點詞用 somewhere。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (70,'{"number":70,"prompt":"Rewrite using anywhere: They went nowhere during the holiday.","answer":"They did not go anywhere during the holiday.","explanation":"否定動詞後用 anywhere 表示哪裏也沒去。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (71,'{"number":71,"prompt":"Choose to go / go: With the shelter closed, they had nowhere _____.","answer":"to go","explanation":"Nowhere to go 表示沒有可去的地方。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (72,'{"number":72,"prompt":"Explain why this can be grammatical: Nobody realised that someone was hiding in the cupboard.","answer":"Both can be true: the hidden person was not noticed.","explanation":"Nobody 是否定「察覺的人」；someone 是「藏着的人」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (73,'{"number":73,"prompt":"Complete the fixed pattern: She is something _____ an authority on local birds.","answer":"of","explanation":"Something of an authority 表示在某程度上是權威。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (74,'{"number":74,"prompt":"Compare the specificity: I want to speak to someone in particular. / I have nothing in particular to discuss. Does the first require the person to be named, and does the second necessarily deny having any topic at all?","answer":"No to both.","explanation":"Someone in particular 不必在句中報名字；nothing in particular 表示沒有特定議題，未必完全沒有話題。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (75,'{"number":75,"prompt":"Replace anybody with the equivalent -one form: Is anybody waiting outside?","answer":"Is anyone waiting outside?","explanation":"Anyone 與 anybody 在這裏同義。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (76,'{"number":76,"prompt":"Use an any- person word: I will check whether _____ has a spare charger.","answer":"anyone / anybody","explanation":"Whether 後中立地查問是否有人有充電器。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (77,'{"number":77,"prompt":"Correct this ordinary single negative: I haven''t told nobody about it.","answer":"I haven''t told anybody about it.","explanation":"普通單重否定寫 haven''t…anybody。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (78,'{"number":78,"prompt":"Complete the tag: Everyone has received a ticket, _____? Use they in the tag.","answer":"haven''t they?","explanation":"Everyone 帶全部人意思，肯定主句的附加問句用否定形式及 they。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (79,'{"number":79,"prompt":"Complete: There is nothing _____ worry about. Use a to-infinitive.","answer":"to","explanation":"Nothing to worry about 是自然不定式結構。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (80,'{"number":80,"prompt":"Choose someone else / other someone: Ask _____ if I am busy.","answer":"someone else","explanation":"Else 放在人稱不定代名詞後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (81,'{"number":81,"prompt":"Compare the emphasis: Is there anything in the box? / Is there anything at all in the box? Does at all turn the second question into a statement that the box is empty?","answer":"No.","explanation":"At all 只加強「到底有沒有」的語氣，沒有斷言箱子空了。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (82,'{"number":82,"prompt":"Correct the ordinary pronoun form: Everythings in this drawer are mine.","answer":"Everything in this drawer is mine.","explanation":"Everything 作單數主語，沒有普通複數 everythings。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (83,'{"number":83,"prompt":"Compare the usual attitudes: Did someone call while I was away? / Did anyone call while I was away?","answer":"Both are possible.","explanation":"Someone 可暗示說話者預期有人來電；anyone 較像開放查問。語境會影響語氣。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (84,'{"number":84,"prompt":"Use a no- thing word: The drawer has been cleared out. _____ remains in it.","answer":"Nothing","explanation":"抽屜已清空，沒有東西留下。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (85,'{"number":85,"prompt":"Complete with a reflexive pronoun referring back to everyone: Everyone introduced _____ at the start.","answer":"themselves","explanation":"指每位參與者本人，單數 they 的反身形式可用 themselves。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (86,'{"number":86,"prompt":"Complete with for / to: There is something _____ you to sign before you leave.","answer":"for","explanation":"For you to sign 明示簽名的人是 you。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (87,'{"number":87,"prompt":"Replace someone else with a natural expression using other than: Ask someone else, not Ray.","answer":"Ask someone other than Ray.","explanation":"Other than Ray 表示另找一人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (88,'{"number":88,"prompt":"Choose is / are: Nowhere _____ safe during the storm. Treat nowhere as the subject.","answer":"was","explanation":"Nowhere 作單數地點主語。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (89,'{"number":89,"prompt":"The speaker says, \"Someone has changed the password.\" Does that reveal who it was? Does it prove the speaker does not know?","answer":"No to both.","explanation":"句子沒報出名字；說話者可能知道，也可能不知道是誰。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (90,'{"number":90,"prompt":"Explain the meaning: The music has a certain something that makes it memorable.","answer":"An appealing but hard-to-name quality.","explanation":"A certain something 指一種說不清卻能感受到的特質。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (91,'{"number":91,"prompt":"Use a no- person word: We called each name, but _____ answered.","answer":"nobody / no one","explanation":"逐個叫名仍沒有人回答。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (92,'{"number":92,"prompt":"Choose is / are: Someone with two large bags _____ waiting at the stop.","answer":"is","explanation":"主語核心是 Someone；with two large bags 不改變單數動詞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (93,'{"number":93,"prompt":"Use a passive infinitive: There is nothing _____ (repair); all the equipment is working.","answer":"to be repaired","explanation":"設備完好，沒有需要修理的東西；用被動不定式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (94,'{"number":94,"prompt":"Put in the usual order: else / anything / to add.","answer":"anything else to add","explanation":"Else 跟在 anything 後，to add 表補充的動作。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (95,'{"number":95,"prompt":"Front the negative place phrase: The guide does not mention the fee anywhere in the leaflet. Begin Nowhere in the leaflet.","answer":"Nowhere in the leaflet does the guide mention the fee.","explanation":"否定地點片語置句首，主句要倒裝。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (96,'{"number":96,"prompt":"Compare: Almost anyone could operate it. / Almost everyone operated it.","answer":"No.","explanation":"Almost anyone could 強調能力或機會幾乎對所有人開放；almost everyone operated 說幾乎所有人確實操作了。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (97,'{"number":97,"prompt":"Explain why a can be natural: I brought a little something for your birthday.","answer":"A little something is a natural special expression for a small gift.","explanation":"這裏的 a 不表示普通 someone/something 都可隨意加冠詞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (98,'{"number":98,"prompt":"Explain the idiom in context: The children suddenly stopped talking when I came in. I suspect they are up to something.","answer":"They may be planning a secret or mischievous action.","explanation":"Be up to something 表示在暗中做某事，常帶可疑語氣。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (99,'{"number":99,"prompt":"Correct the ordinary meaning \"an unidentified person is outside\": A someone is outside.","answer":"Someone is outside.","explanation":"普通「未指名的人」用 someone，不加 a。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (100,'{"number":100,"prompt":"Compare the likely attitudes: Didn''t you bring something to read? / Didn''t you bring anything to read?","answer":"Both are possible.","explanation":"Something 往往暗示原以為對方有帶；anything 可帶「連一點也沒有嗎」的意外語氣。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (101,'{"number":101,"prompt":"Complete: It is not my scarf. It is _____ (somebody else).","answer":"somebody else''s","explanation":"所有格的 ''s 加在 else 後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (102,'{"number":102,"prompt":"Front the negative place phrase: I did not see the warning anywhere in the building. Begin Nowhere in the building.","answer":"Nowhere in the building did I see the warning.","explanation":"否定地點片語置句首，過去式用 did 倒裝。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (103,'{"number":103,"prompt":"Explain the exception: Nobody but the caretaker has a key. Who is excluded from the zero-person claim?","answer":"The caretaker.","explanation":"But 排除看門人；其他人都沒有匙。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (104,'{"number":104,"prompt":"Explain something like: The repair cost something like ninety dollars.","answer":"Approximately ninety dollars.","explanation":"Something like 在此表示大約，非物件相似。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (105,'{"number":105,"prompt":"Explain the evaluation: The rescue was nothing short of extraordinary. Is the praise weakened or made emphatic?","answer":"Made emphatic.","explanation":"Nothing short of extraordinary 是高度讚賞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (106,'{"number":106,"prompt":"Someone has moved the tables. Does this sentence by itself prove that exactly one person, with no helpers, did all the work? Explain.","answer":"No.","explanation":"Someone 指有未指明的人參與；句子未提供精確人數或幫手資料。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (107,'{"number":107,"prompt":"Complete with an any- person word: The instructions are so clear that _____ can follow them, regardless of experience.","answer":"anyone / anybody","explanation":"不限制經驗程度，任何人都可依照指示。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (108,'{"number":108,"prompt":"Use an every- thing word: I checked all the items on the list. _____ was correct.","answer":"Everything","explanation":"清單上所有項目都正確。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (109,'{"number":109,"prompt":"Choose is / are: Someone and their assistant _____ checking the room.","answer":"are","explanation":"Someone and their assistant 是兩人，複數主語配 are。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (110,'{"number":110,"prompt":"Choose waiting / waited: There is somebody _____ outside. They arrived a minute ago and have not left.","answer":"waiting","explanation":"Somebody waiting outside 描述此刻仍在外面等的人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (111,'{"number":111,"prompt":"Choose nothing / anything: The final design was _____ like the original; it had changed completely.","answer":"nothing","explanation":"Nothing like the original 表示與原設計很不相似。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (112,'{"number":112,"prompt":"Explain anything goes: At this costume party, anything goes; guests may wear whatever they like.","answer":"Guests may wear almost any costume.","explanation":"Anything goes 指規則寬鬆、各種做法都可接受；仍受活動實際規則限制。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (113,'{"number":113,"prompt":"I know someone who can translate this: my uncle. Is someone impossible because the speaker knows the person''s identity?","answer":"No.","explanation":"說話者可知道身份，只是沒有在這句說名字。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (114,'{"number":114,"prompt":"Use an any- place word: There are no reserved seats. Sit _____ you like.","answer":"anywhere","explanation":"沒有指定座位，讓對方任選地方坐。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (115,'{"number":115,"prompt":"Use a no- place word: All the car parks were full. There was _____ to park.","answer":"nowhere","explanation":"全部停車場滿了，沒有地方泊車。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (116,'{"number":116,"prompt":"Correct the ordinary statement: Everybody have finished their lunch.","answer":"Everybody has finished their lunch.","explanation":"Everybody 作單數主語，配 has。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (117,'{"number":117,"prompt":"Choose left / leaving: We have eaten all the food. There is nothing _____.","answer":"left","explanation":"食物全吃光，nothing left 表示沒有剩餘。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (118,'{"number":118,"prompt":"Expand ''s as is / has / possessive: Somebody''s waiting downstairs.","answer":"is","explanation":"Somebody is waiting downstairs；''s 是 is。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (119,'{"number":119,"prompt":"Choose normal / inverted word order: Everywhere we went, people welcomed us. Does everywhere require inversion here?","answer":"Normal order.","explanation":"Everywhere 並非否定地點詞，此句不用倒裝。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (120,'{"number":120,"prompt":"Explain the available choice: You may choose anything except the smallest box.","answer":"Any available item except the smallest box.","explanation":"Anything 給任選自由，except 明確排除一件。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (121,'{"number":121,"prompt":"Use a some- thing word in a simple request: Please bring _____ to share at lunch.","answer":"something","explanation":"請求帶點東西分享，用 something。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (122,'{"number":122,"prompt":"Use an every- place word: The paint splashed over the floor, the walls and the furniture. It went _____.","answer":"everywhere","explanation":"油漆濺到整個相關空間各處。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (123,'{"number":123,"prompt":"Choose is / are: Something in these boxes _____ making a noise.","answer":"is","explanation":"主語核心是 Something，配單數 is。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (124,'{"number":124,"prompt":"Choose whose / who: I met someone _____ daughter plays in the orchestra.","answer":"whose","explanation":"Whose daughter 表示那人的女兒。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (125,'{"number":125,"prompt":"Expand ''s as is / has / possessive: Someone''s already opened the parcel.","answer":"has","explanation":"Someone has already opened the parcel；''s 是 has。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (126,'{"number":126,"prompt":"Replace somewhere else with one word: Please take the conversation somewhere else.","answer":"Please take the conversation elsewhere.","explanation":"Elsewhere 可代替 somewhere else。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (127,'{"number":127,"prompt":"I told my cousin, and nobody else. Does nobody else include my cousin among the people I did not tell?","answer":"No.","explanation":"Nobody else 排除已提到的表姐，意思是其他人都不知道。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (128,'{"number":128,"prompt":"Explain the question: Is this sample anything like the material you wanted?","answer":"Is it at all similar to the material you wanted?","explanation":"Anything like 在這裏問相似程度。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (129,'{"number":129,"prompt":"Explain the decision: We must accept the whole package or reject it completely. It is an all-or-nothing choice.","answer":"We must choose one whole option, without a partial compromise.","explanation":"All-or-nothing 表示只能全取或全不取。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (130,'{"number":130,"prompt":"Choose someone / something: _____ unexpected happened during the rehearsal: the lights went out.","answer":"Something","explanation":"燈突然熄滅，發生的是一件事。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (131,'{"number":131,"prompt":"Can who be omitted? Anyone who needs help should raise a hand. Explain its role.","answer":"No.","explanation":"Who 是關係子句的主語，直接連接 anyone 與 needs help。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (132,'{"number":132,"prompt":"Identify ''s as is / has / possessive: I found somebody''s gloves.","answer":"possessive","explanation":"Somebody''s gloves 表示某人的手套。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (133,'{"number":133,"prompt":"In American usage, what usual -where word can replace someplace in She needs someplace to sit?","answer":"somewhere","explanation":"美式 someplace 在此可用 somewhere 代替。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (134,'{"number":134,"prompt":"Explain: We cannot give the access code to just anybody. Does this mean we can give it to no one at all?","answer":"No.","explanation":"Just anybody 指未經挑選的任何人；仍可交給獲授權的人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (135,'{"number":135,"prompt":"Explain if anything: If anything, the second route is shorter, not longer.","answer":"The second route may actually be shorter.","explanation":"If anything 在此把判斷推向「更短」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (136,'{"number":136,"prompt":"Explain the exaggeration: Sam packed everything but the kitchen sink for a one-night stay. Must this literally mean every object except one sink?","answer":"No.","explanation":"Everything but the kitchen sink 誇張地說帶了太多東西。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (137,'{"number":137,"prompt":"Choose everyone / everything: All the equipment has been tested. _____ is working properly.","answer":"Everything","explanation":"設備全都檢查過，談的是物件。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (138,'{"number":138,"prompt":"Use an any- thing word: They refused to reveal _____ about the new design.","answer":"anything","explanation":"Refused to reveal 是否定動詞片語，任何設計資料都不透露。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (139,'{"number":139,"prompt":"Rewrite using nothing: He did not say anything rude at yesterday''s meeting.","answer":"He said nothing rude at yesterday''s meeting.","explanation":"Nothing rude 表示沒有說粗魯的話。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (140,'{"number":140,"prompt":"Complete: Has anyone _____ (see) the new timetable?","answer":"seen","explanation":"Has 後用過去分詞 seen。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (141,'{"number":141,"prompt":"Twenty pupils entered; three did not finish. Choose a true statement: Nobody finished. / Not everyone finished.","answer":"Not everyone finished.","explanation":"二十人中三人未完成，故並非所有人都完成。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (142,'{"number":142,"prompt":"Explain if nothing else: If nothing else, we learnt how to cooperate.","answer":"At minimum, the project taught us cooperation.","explanation":"If nothing else 表示至少這點收穫成立。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (143,'{"number":143,"prompt":"Explain the limit on knowledge: As far as anyone knows, the tunnel is unused. Does this guarantee that no hidden user exists?","answer":"No.","explanation":"As far as anyone knows 只限於目前所知，不保證不存在未發現的使用者。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (144,'{"number":144,"prompt":"Choose anyone / anywhere: I have not spoken to _____ about the result.","answer":"anyone / anybody","explanation":"Not spoken to anyone 表示沒有向任何人談結果。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (145,'{"number":145,"prompt":"Use an any- person word: She left without thanking _____.","answer":"anyone / anybody","explanation":"Without thanking anyone 表示沒向任何人致謝。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (146,'{"number":146,"prompt":"Correct the ordinary zero-person meaning: Anyone came to the empty office that day. Use a no- word.","answer":"Nobody came to the empty office that day.","explanation":"零人到訪，選自帶否定的 nobody。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (147,'{"number":147,"prompt":"Rewrite as a question: Somebody knows the answer. Use Does anyone.","answer":"Does anyone know the answer?","explanation":"一般問句用 does 加動詞原形，開放查問任何人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (148,'{"number":148,"prompt":"Omit the relative word where possible: She is someone whom I trust.","answer":"She is someone I trust.","explanation":"Whom 在限制性關係子句中作受詞，這裏可省略。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (149,'{"number":149,"prompt":"Correct the ordinary partitive: I asked someone of the players. Use one of.","answer":"I asked one of the players.","explanation":"指定球員群組中的一位，用 one of。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (150,'{"number":150,"prompt":"Rewrite in ordinary standard English: We have nowheres to wait.","answer":"We have nowhere to wait.","explanation":"普通標準英語用 nowhere，不能加複數 -s。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (151,'{"number":151,"prompt":"Choose somebody / something: The winner was _____ from the evening class, but I do not know their name.","answer":"somebody","explanation":"獲獎者是一個人而非物件。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (152,'{"number":152,"prompt":"Use an any- person word: Hardly _____ noticed the small change.","answer":"anyone / anybody","explanation":"Hardly anyone 表示幾乎沒有人注意到。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (153,'{"number":153,"prompt":"Rewrite using anywhere: There is nowhere safe to leave the bicycles.","answer":"There isn''t anywhere safe to leave the bicycles.","explanation":"否定動詞加 anywhere 表示沒有安全地點。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (154,'{"number":154,"prompt":"Identify the role of someone: The coach spoke to someone after the game. Choose subject / object of a preposition.","answer":"object of the preposition","explanation":"Someone 接在 to 後，是介詞受詞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (155,'{"number":155,"prompt":"Correct the repeated object: This is something I bought it in Kyoto.","answer":"This is something I bought in Kyoto.","explanation":"Something 已是 bought 的受詞，不再加 it。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (156,'{"number":156,"prompt":"Correct: Everyone of the computers has been tested.","answer":"Every one of the computers has been tested.","explanation":"Every one of 明確逐部指一組電腦。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (157,'{"number":157,"prompt":"Omit the second where if natural: We need somewhere where we can practise without disturbing anyone.","answer":"We need somewhere we can practise without disturbing anyone.","explanation":"Where 在此可省略；somewhere 本身表地點。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (158,'{"number":158,"prompt":"Rewrite to remove the intended partial-negative ambiguity: Everyone isn''t ready. Mean that at least one person is not ready, without saying nobody is ready.","answer":"Not everyone is ready.","explanation":"只表示至少一人未準備好，沒有說全部未準備好。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (159,'{"number":159,"prompt":"Explain the vagueness: We could visit a gallery or something.","answer":"We might visit a gallery or a similar place.","explanation":"Or something 留下未說明的相近選擇，語氣較隨意。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (160,'{"number":160,"prompt":"Choose asking / to ask after with: There is nothing wrong with _____ for clearer instructions.","answer":"asking","explanation":"介詞 with 後接動名詞 asking。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (161,'{"number":161,"prompt":"Identify the role of somebody: The missing actor was somebody from our school. Choose complement / location adverb.","answer":"complement","explanation":"Somebody from our school 是主語的補語，說明失蹤演員的身份。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (162,'{"number":162,"prompt":"Correct the repeated object: He is someone I can rely on him.","answer":"He is someone I can rely on.","explanation":"Someone 已是 rely on 的對象，不再加 him。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (163,'{"number":163,"prompt":"Correct: Anyone of the four routes is suitable.","answer":"Any one of the four routes is suitable.","explanation":"明確從四條路選其中一條，用 any one of。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (164,'{"number":164,"prompt":"Rewrite using wherever: You may put the chair anywhere you like.","answer":"You may put the chair wherever you like.","explanation":"Wherever 表示放在哪裏都可以。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (165,'{"number":165,"prompt":"Compare: There is something I haven''t checked. / I haven''t checked anything.","answer":"No.","explanation":"第一句尚有至少一件事沒檢查；第二句表示完全沒有檢查任何事。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (166,'{"number":166,"prompt":"Explain or anything: I didn''t complain or anything.","answer":"I didn''t complain or do anything similar.","explanation":"Or anything 用口語方式概括相近行為。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (167,'{"number":167,"prompt":"Complete with everyone / everything: Before the concert, the microphones, lights and chairs were checked: _____ was ready. Then all the performers arrived: _____ was present.","answer":"Everything was ready. Everyone was present.","explanation":"器材用 everything；表演者用 everyone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (168,'{"number":168,"prompt":"Choose something / somewhere: The report contains _____ important about the water supply.","answer":"something","explanation":"報告有一項關於供水的重要資訊。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (169,'{"number":169,"prompt":"Complete with an any- thing word: I am too tired to do _____ demanding tonight.","answer":"anything","explanation":"Too tired to do anything demanding 表示不想做任何費神的事。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (170,'{"number":170,"prompt":"Rewrite using anything: There is nothing more to add.","answer":"There isn''t anything more to add.","explanation":"Nothing 可改成否定動詞加 anything。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (171,'{"number":171,"prompt":"Choose anywhere / everywhere for a numerical range: Repairs can cost _____ from twenty to eighty pounds.","answer":"anywhere","explanation":"Anywhere from twenty to eighty 表示數值範圍。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (172,'{"number":172,"prompt":"For the ordinary meaning \"no person at any time,\" correct: Nobody has never used this entrance.","answer":"Nobody has ever used this entrance.","explanation":"普通單重否定由 nobody 表達；ever 表任何時候。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (173,'{"number":173,"prompt":"Explain the expression: She was reading something or other about ancient maps.","answer":"Some unspecified article about ancient maps.","explanation":"Something or other 表示未說清或不記得具體是哪一篇。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (174,'{"number":174,"prompt":"Write five connected sentences beginning Someone knocked on the window. Include something, a place word and a no- word. Use they to continue referring to the visitor, then reveal who they are in the final sentence.","answer":"Someone knocked on the window. They were holding something small. They pointed towards somewhere beyond the garden. Nothing moved there at first. Then I recognised them: it was our neighbour Mei.","explanation":"參考短文；人稱 they 始終指同一訪客，最後一句揭示身份。其他連貫寫法也可。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (175,'{"number":175,"prompt":"Explain the special noun use: After winning several awards, she became a somebody in the art world. Does a somebody mean an important person or simply an unidentified person?","answer":"An important or well-known person.","explanation":"A somebody 是特殊可數名詞用法，並非普通「未指名的人」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (176,'{"number":176,"prompt":"Use an any- person word: We will keep the date unless _____ objects.","answer":"anyone / anybody","explanation":"Unless anyone objects 表示若無人反對就維持日期。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (177,'{"number":177,"prompt":"Complete with an any- person word: She seldom speaks to _____ outside her team.","answer":"anyone / anybody","explanation":"Seldom 具近乎否定的意思，常配 anyone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (178,'{"number":178,"prompt":"Choose their / its for a person of unknown gender: Someone has forgotten _____ coat.","answer":"their","explanation":"性別未明的人可用單數 they 的所有格 their。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (179,'{"number":179,"prompt":"Choose wants / want: You may take anything you _____.","answer":"want","explanation":"You 是關係子句主語，配 want。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (180,'{"number":180,"prompt":"Choose no / none: There is _____ milk in the fridge.","answer":"no","explanation":"No milk 表示沒有牛奶；none 不直接修飾 milk。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (181,'{"number":181,"prompt":"Complete a neutral enquiry and its answer: A: Does _____ know where the spare key is? B: No, _____ does; the location was never recorded. Use an any- person word, then a no- person word.","answer":"Does anyone know where the spare key is? No, nobody does.","explanation":"問句開放查問；回答說無人知道。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (182,'{"number":182,"prompt":"Use the -one equivalent of nobody: Nobody recognised the handwriting.","answer":"No one recognised the handwriting.","explanation":"No one 與 nobody 在此同義。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (183,'{"number":183,"prompt":"Use a some- thing word: I hope to learn _____ useful from the visit. Does this claim the visit has already happened? Answer both parts.","answer":"I hope to learn something useful from the visit. No, the visit need not have happened yet.","explanation":"Hope 指未來期望，不能推斷已經學到。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (184,'{"number":184,"prompt":"Complete with ever / never: Nobody has _____ explained why the alarm sounds. Keep the ordinary meaning of no explanation at any time.","answer":"ever","explanation":"Nobody 已帶否定；ever 表「任何時候」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (185,'{"number":185,"prompt":"Choose they / it to refer to a thing: Something is blocking the pipe. _____ must be removed.","answer":"It","explanation":"指堵住水管的物件，用 it。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (186,'{"number":186,"prompt":"Choose wants / want: She will bring anything her brother _____.","answer":"wants","explanation":"Her brother 是單數主語，配 wants。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (187,'{"number":187,"prompt":"Choose no / none: I wanted some milk, but there was _____ left.","answer":"none","explanation":"None left 回指先前提到的牛奶。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (188,'{"number":188,"prompt":"Use somewhere to express approximation: The journey takes _____ around forty minutes.","answer":"somewhere","explanation":"Somewhere around forty minutes 表大約四十分鐘。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (189,'{"number":189,"prompt":"Explain why the rule \"an entire sentence may contain only one negative word\" is too broad. Use It is not true that nobody objected as your example.","answer":"It is not true that nobody objected.","explanation":"Not 否定的是整個「無人反對」的說法；兩個否定詞作用在不同層次。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (190,'{"number":190,"prompt":"Complete: You look distracted. Do you have something _____ your mind?","answer":"on","explanation":"Have something on your mind 表示心裏有事。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (191,'{"number":191,"prompt":"Use an every- person word: The invitation is for the whole class, not just a few pupils. _____ is welcome.","answer":"Everyone / Everybody","explanation":"邀請全班，每個人都受歡迎。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (192,'{"number":192,"prompt":"Correct: Everyone is ready, isn''t they? Use the normal they tag.","answer":"Everyone is ready, aren''t they?","explanation":"Everyone 可配單數 they 附加問句；肯定主句用否定附加問句。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (193,'{"number":193,"prompt":"Are both relative words acceptable in standard English? I found something that may help. / I found something which may help. Do not treat a preference for that as a ban on which.","answer":"Yes, both that and which are acceptable.","explanation":"Something 後常偏好 that，但標準用法並不一概排除 which。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (194,'{"number":194,"prompt":"Choose is / are with an uncountable referent: None of the water _____ safe to drink.","answer":"is","explanation":"Water 是不可數名詞；none of the water 配 is。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (195,'{"number":195,"prompt":"Explain the degree meaning: The work is nowhere near finished.","answer":"The work is far from finished.","explanation":"Nowhere near 加強「距完成還很遠」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (196,'{"number":196,"prompt":"Compare: Somebody called this morning. / Anybody may call this number.","answer":"Somebody called reports an actual caller; anybody may call grants permission to any caller.","explanation":"前者說有人已來電；後者說打電話的資格不限。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (197,'{"number":197,"prompt":"Complete: This delay has nothing to do _____ the weather.","answer":"with","explanation":"Have nothing to do with 表示與某事無關。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (198,'{"number":198,"prompt":"Both can be grammatical: Her answer was unlike anyone else''s. / Her answer was unlike everyone else''s. Explain the usual comparison focus instead of declaring either form always wrong.","answer":"Both are grammatical.","explanation":"Anyone else''s 常突出任意另一人；everyone else''s 把比較範圍指向其他所有人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (199,'{"number":199,"prompt":"Rewrite without naming the person. Begin I met someone and keep the information: I met my neighbour, who repairs cameras.","answer":"I met someone who repairs cameras.","explanation":"保留「會修相機」的資訊，但不報出鄰居身份。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (200,'{"number":200,"prompt":"Compare the likely attitudes: Didn''t someone warn you? / Didn''t anyone warn you? Can the first suggest an expected warning, while the second can express surprise that there was no warning?","answer":"Yes, depending on context.","explanation":"Someone 可暗示原以為有人提醒；anyone 可表達意外地似乎沒有人提醒。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (201,'{"number":201,"prompt":"Are both forms possible in standard usage? None of the volunteers is available. / None of the volunteers are available. Explain briefly.","answer":"Yes, both can occur.","explanation":"None of a plural group may take singular is or plural are；語境及風格可影響選擇。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (202,'{"number":202,"prompt":"Complete the usual fixed phrase: I searched every drawer, but the receipt was nowhere to be _____.","answer":"found","explanation":"Nowhere to be found 是固定表達。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (203,'{"number":203,"prompt":"Six people were invited. Not everyone came. Which must be true: at least one did not come / at least one came?","answer":"At least one did not come.","explanation":"Not everyone 不保證有人到場，只保證並非六人全到。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (204,'{"number":204,"prompt":"Explain none other than: The surprise guest was none other than our old music teacher.","answer":"The surprise guest was our old music teacher.","explanation":"None other than 強調意外或令人驚喜的身份。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (205,'{"number":205,"prompt":"The narrator writes Someone had left a note. In the next sentence, the narrator reveals that the writer was Mei. Must the first sentence be changed to anyone just because the identity becomes known? Explain.","answer":"No.","explanation":"Someone 只是先不說姓名；下一句可以補充身份。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (206,'{"number":206,"prompt":"Does everybody normally refer to every person, or to each physical body treated as an object?","answer":"Every person.","explanation":"Everybody 是人的不定代名詞，普通用法並非逐具身體。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (207,'{"number":207,"prompt":"Use an any- thing word: If you notice _____ unusual, report it.","answer":"anything","explanation":"If 後尚未確定會否見到異常情況。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (208,'{"number":208,"prompt":"Rewrite as a natural sentence using no one: There isn''t anyone who remembers the old code.","answer":"No one remembers the old code.","explanation":"No one 自帶否定，不再加 isn''t。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (209,'{"number":209,"prompt":"Explain why both verb forms can be correct: Someone is outside. They are waiting for a taxi.","answer":"Someone is outside. They are waiting for a taxi.","explanation":"Someone 作單數主語；they 作代詞時配 are。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (210,'{"number":210,"prompt":"Correct the ordinary relative pattern: There is something what I need to tell you.","answer":"There is something that I need to tell you.","explanation":"That 可引出關係子句；what 不可直接這樣修飾 something。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (211,'{"number":211,"prompt":"Explain the positive meaning: The plan is nothing if not ambitious.","answer":"The plan is very ambitious.","explanation":"Nothing if not ambitious 強調「十分有雄心」，屬正面程度表達。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (212,'{"number":212,"prompt":"Write two short sentences about a library: one using somewhere plus an adjective, and one using someone plus a relative clause beginning who. Keep the place and person meanings distinct.","answer":"The library is somewhere quiet to read. I know someone who works there.","explanation":"參考作答；somewhere 指地方，someone who 指人。其他自然且符合要求的句子也可。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (213,'{"number":213,"prompt":"Explain the difference in word division: nowhere / now here.","answer":"Nowhere means in no place; now here means here at the present time.","explanation":"連寫與分寫改變意思。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (214,'{"number":214,"prompt":"Compare the instructions: Take something from the shelf. / Take anything you like from the shelf.","answer":"Take something asks for an unspecified item; take anything you like permits unrestricted choice.","explanation":"兩句的選擇範圍不同。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (215,'{"number":215,"prompt":"Rewrite using anything and the correct past form: The witness noticed nothing unusual.","answer":"The witness didn''t notice anything unusual.","explanation":"過去時間用 didn''t notice，否定範圍內用 anything。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (216,'{"number":216,"prompt":"Choose itself / themselves for a thing: Something on the shelf moved all by _____; no person touched it.","answer":"itself","explanation":"Something 指物件，反身代詞用 itself。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (217,'{"number":217,"prompt":"Choose worth keeping / worth to keep: This note is something _____.","answer":"worth keeping","explanation":"Worth 後通常接動名詞 keeping。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (218,'{"number":218,"prompt":"Rewrite using all the students and adjust the verb: Everyone in the class is ready.","answer":"All the students in the class are ready.","explanation":"複數主語 students 配 are。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (219,'{"number":219,"prompt":"Explain the figurative meaning: We argued for an hour and got nowhere.","answer":"We made no progress.","explanation":"Got nowhere 在此是比喻，表示爭論沒有結果。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (220,'{"number":220,"prompt":"At the theatre, the usher says \"Everyone is inside.\" Must everyone mean every human being in the world? Explain the likely domain.","answer":"No.","explanation":"Everyone 在劇院語境指當時談到的相關人員，通常非全世界的人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (221,'{"number":221,"prompt":"Use a some- person word: I can hear footsteps. Has _____ come back early?","answer":"someone / somebody","explanation":"聽到腳步聲，說話者有理由懷疑有人回來。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (222,'{"number":222,"prompt":"Choose almost nobody / almost everybody: Out of 100 people, 99 approved the plan. _____ approved it.","answer":"Almost everybody","explanation":"一百人中九十九人贊成，幾乎所有人贊成。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (223,'{"number":223,"prompt":"Choose was / were: Everyone in the two teams _____ given a badge.","answer":"was","explanation":"Everyone 作單數主語，即使涉及兩隊仍配 was。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (224,'{"number":224,"prompt":"Complete with a place phrase: She lives somewhere _____. Use near / station / the in the normal order.","answer":"near the station","explanation":"Somewhere near the station 是自然語序。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (225,'{"number":225,"prompt":"Choose everyone / every one: I checked five answers and _____ was correct. Refer to each of the five answers.","answer":"every one","explanation":"逐一指五個答案，寫 every one。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (226,'{"number":226,"prompt":"Complete the fixed phrase: The cottage is in the middle of _____. It is miles from the nearest village.","answer":"nowhere","explanation":"In the middle of nowhere 指偏僻地方。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (227,'{"number":227,"prompt":"Which word choice does not claim exactly which person? I saw someone waiting / I saw our librarian waiting. Explain.","answer":"I saw someone waiting.","explanation":"Someone 不報具體身份；our librarian 已說出是誰。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (228,'{"number":228,"prompt":"Complete with the normal preposition: There is nothing to worry _____.","answer":"about","explanation":"Nothing to worry about 是自然搭配。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (229,'{"number":229,"prompt":"In a story, the dishonest guard says, \"Nobody knows about this door.\" Later, a child shows that she knows about it. Is nobody grammatically wrong just because the guard''s claim was false? Explain.","answer":"No.","explanation":"句子文法成立；故事後來證明守衛的事實主張錯了。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (230,'{"number":230,"prompt":"The witness says, \"Somebody took it, but I do not want to name them.\" Must somebody mean that the witness does not know who took it?","answer":"No.","explanation":"Somebody 只是不在句中說名字；證人甚至可能有意隱瞞身份。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (231,'{"number":231,"prompt":"Put in a natural order: something / more / practical / a little.","answer":"something a little more practical","explanation":"形容詞片語置於 something 後。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (232,'{"number":232,"prompt":"Explain the difference: nobody / no body. Use the ordinary person pronoun versus body as a separate noun referring to a physical body.","answer":"Nobody = no person; no body = no physical body.","explanation":"分開兩字時，body 是普通名詞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (233,'{"number":233,"prompt":"Is from somewhere automatically wrong? A letter arrived from somewhere in South America. Explain the preposition.","answer":"No.","explanation":"From somewhere 自然表示來源；from 是介詞，somewhere 是地點。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (234,'{"number":234,"prompt":"In The young actor was treated as a nobody, is nobody the ordinary pronoun meaning no person, or a countable noun meaning an unimportant person?","answer":"A countable noun meaning an unimportant person.","explanation":"A nobody 是特殊名詞用法。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (235,'{"number":235,"prompt":"Complete both infinitive patterns: There was nothing to do but _____. / We had no choice but _____. Use wait.","answer":"There was nothing to do but wait. / We had no choice but to wait.","explanation":"Nothing to do but 後接原形；no choice but 後接 to 不定式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (236,'{"number":236,"prompt":"Explain the special use of something else: After an astonishing performance, a listener says, \"That singer is really something else!\" Must this mean a different object rather than a person?","answer":"No.","explanation":"Really something else 可讚嘆表演者出眾，並非說他是另一件物件。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (237,'{"number":237,"prompt":"Choose something / someone: I have _____ to suggest: we could move the meeting online.","answer":"something","explanation":"要提出的是一個建議或想法。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (238,'{"number":238,"prompt":"Use an any- person word: I doubt whether _____ can repair it before tomorrow.","answer":"anyone / anybody","explanation":"Doubt whether 表示不確定是否有人能趕及修好。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (239,'{"number":239,"prompt":"Choose hardly anyone / hardly nobody for ordinary standard writing: _____ could hear the announcement.","answer":"Hardly anyone","explanation":"普通標準用法以 hardly anyone 表幾乎沒有人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (240,'{"number":240,"prompt":"Explain the form of everyone in Hello, everyone! Is it a normal statement subject requiring knows or is after it?","answer":"A form of direct address, not a statement subject.","explanation":"Hello, everyone! 是招呼語，不需要再接 is 或 knows。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (241,'{"number":241,"prompt":"Both are possible: Anyone in this class can solve it. / Everyone in this class can solve it. Explain the difference in focus rather than marking one automatically wrong.","answer":"Both are possible.","explanation":"Anyone 強調資格對每位同學開放；everyone 強調整個班都有能力。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (242,'{"number":242,"prompt":"Compare the two meanings of for nothing: We got the tickets for nothing. / We waited all afternoon for nothing; the office never opened.","answer":"First: free of charge. Second: without a useful result.","explanation":"For nothing 在不同語境可指免費或白費工夫。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (243,'{"number":243,"prompt":"Complete the three gaps using somewhere / someone / nothing, each once, then check the whole passage for consistency: We needed _____ dry to wait. Then _____ offered us a seat in a covered shelter. We had _____ to complain about: the place was warm and the staff were kind.","answer":"We needed somewhere dry to wait. Then someone offered us a seat in a covered shelter. We had nothing to complain about.","explanation":"地方、人、零抱怨分別用 somewhere、someone、nothing，語意連貫。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (244,'{"number":244,"prompt":"Name the category of each word: someone, anything, everywhere. Write person / thing or matter / place.","answer":"someone: person; anything: thing or matter; everywhere: place.","explanation":"按所指的人、事情、地點分類。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (245,'{"number":245,"prompt":"Use an any- word, then explain its meaning: _____ may submit a design; entry is open to all.","answer":"Anyone may submit a design: entry is open to all.","explanation":"肯定句的 anyone 表示任意人均可，不表示所有人已提交。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (246,'{"number":246,"prompt":"Rewrite to emphasise zero available action using nothing: There isn''t anything we can do now.","answer":"There is nothing we can do now.","explanation":"Nothing 強調零個可採取的行動。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (247,'{"number":247,"prompt":"Choose themselves / itself for a human referent: Someone has accidentally locked _____ out.","answer":"themselves","explanation":"未知性別的人可用單數 they 的反身形式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (248,'{"number":248,"prompt":"Use an explicit infinitive subject: We need somewhere _____ the children _____ rest. Insert for and to.","answer":"We need somewhere for the children to rest.","explanation":"For 明示動作主語 children；to 引出不定式。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (249,'{"number":249,"prompt":"Join using nobody else: My sister knew the code. No other person did.","answer":"My sister knew the code, but nobody else did.","explanation":"Nobody else 排除姐姐，說其他人都不知道。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into grammar_admin_private.indefinite_pronouns_key(number,data) values (250,'{"number":250,"prompt":"Compare the structures: We went somewhere remote. / It was a road to nowhere. Does the second prove that the first needs to?","answer":"No.","explanation":"Went somewhere remote 直接用地點副詞；a road to nowhere 中的 to 是介詞片語的一部分。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (1,'{"number":1,"sentence":"Someone left a blue scarf on the library desk this morning.","mark":"tick","wrong":"","fix":"","correct_sentence":"Someone left a blue scarf on the library desk this morning.","reason":"Someone 指未指名的人；left 的過去時間與 this morning 相符。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (2,'{"number":2,"sentence":"Noone had written a name on the label.","mark":"cross","wrong":"Noone","fix":"No one","correct_sentence":"No one had written a name on the label.","reason":"普通標準拼法是分開兩字的 no one。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (3,'{"number":3,"sentence":"Our librarian asked whether anyone had seen the owner.","mark":"tick","wrong":"","fix":"","correct_sentence":"Our librarian asked whether anyone had seen the owner.","reason":"Whether anyone 表示中立查問是否有人見過物主。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (4,'{"number":4,"sentence":"Somebody were waiting near the returns counter.","mark":"cross","wrong":"were","fix":"was","correct_sentence":"Somebody was waiting near the returns counter.","reason":"Somebody 作單數主語，配 was。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (5,'{"number":5,"sentence":"Everything in the box was labelled.","mark":"tick","wrong":"","fix":"","correct_sentence":"Everything in the box was labelled.","reason":"Everything 作單數主語，配 was。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (6,'{"number":6,"sentence":"The librarian found a something under a stack of books.","mark":"cross","wrong":"a something","fix":"something","correct_sentence":"The librarian found something under a stack of books.","reason":"普通的不定代名詞 something 前不加冠詞。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (7,'{"number":7,"sentence":"A tiny device began making a strange sound; something was wrong with it.","mark":"tick","wrong":"","fix":"","correct_sentence":"A tiny device began making a strange sound; something was wrong with it.","reason":"Something was wrong 表示有某個未說明的問題。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (8,'{"number":8,"sentence":"The librarian hoped to find someone who could fix it.","mark":"tick","wrong":"","fix":"","correct_sentence":"The librarian hoped to find someone who could fix it.","reason":"Someone who could fix it 指可能修理裝置的人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (9,'{"number":9,"sentence":"The volunteer asked something to carry the heavy bag.","mark":"cross","wrong":"something","fix":"someone","correct_sentence":"The volunteer asked someone to carry the heavy bag.","reason":"搬袋子的是人，應用 someone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (10,'{"number":10,"sentence":"Would you like something warm to drink while you wait?","mark":"tick","wrong":"","fix":"","correct_sentence":"Would you like something warm to drink while you wait?","reason":"提供熱飲的問句可自然用 something。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (11,'{"number":11,"sentence":"I didn''t see nobody in the reading room.","mark":"cross","wrong":"didn''t see nobody","fix":"didn''t see anybody","correct_sentence":"I didn''t see anybody in the reading room.","reason":"普通單重否定用 didn''t see anybody。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (12,'{"number":12,"sentence":"Nobody has claimed the device so far.","mark":"tick","wrong":"","fix":"","correct_sentence":"Nobody has claimed the device so far.","reason":"Nobody 自帶否定，has claimed 的形式正確。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (13,'{"number":13,"sentence":"Someone called from the corridor, but we could not see their face.","mark":"tick","wrong":"","fix":"","correct_sentence":"Someone called from the corridor, but we could not see their face.","reason":"Someone 指未露面的人；their 可指性別未明的單數人物。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (14,'{"number":14,"sentence":"Everythings on the desk belonged to different visitors.","mark":"cross","wrong":"Everythings","fix":"Everything","correct_sentence":"Everything on the desk belonged to different visitors.","reason":"普通代名詞 everything 沒有複數 -s。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (15,'{"number":15,"sentence":"The girl said she knew someone who repairs radios.","mark":"tick","wrong":"","fix":"","correct_sentence":"The girl said she knew someone who repairs radios.","reason":"知道身份的人仍可用 someone；關係子句 who repairs radios 修飾人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (16,'{"number":16,"sentence":"Does anybody knows who owns this device?","mark":"cross","wrong":"knows","fix":"know","correct_sentence":"Does anybody know who owns this device?","reason":"Does 後接動詞原形 know。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (17,'{"number":17,"sentence":"The librarian told everyone to check their bags.","mark":"tick","wrong":"","fix":"","correct_sentence":"The librarian told everyone to check their bags.","reason":"Everyone 作單數主語，their 可回指不指定性別的各人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (18,'{"number":18,"sentence":"Someone''s bag was still under the table.","mark":"tick","wrong":"","fix":"","correct_sentence":"Someone''s bag was still under the table.","reason":"Someone''s bag 是所有格，表示某人的袋。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (19,'{"number":19,"sentence":"Everyone were relieved when the owner arrived.","mark":"cross","wrong":"were","fix":"was","correct_sentence":"Everyone was relieved when the owner arrived.","reason":"Everyone 作單數主語，配 was。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (20,'{"number":20,"sentence":"The owner thanked everybody and took the device home.","mark":"tick","wrong":"","fix":"","correct_sentence":"The owner thanked everybody and took the device home.","reason":"Everybody 是 thanked 的受詞，指全部相關人員。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (21,'{"number":21,"sentence":"Please take something eat before the performance begins.","mark":"cross","wrong":"something eat","fix":"something to eat","correct_sentence":"Please take something to eat before the performance begins.","reason":"Something 後用 to eat 表可吃的東西。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (22,'{"number":22,"sentence":"You may choose anything from the vegetarian table.","mark":"tick","wrong":"","fix":"","correct_sentence":"You may choose anything from the vegetarian table.","reason":"肯定句的 anything 表示從餐桌任選。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (23,'{"number":23,"sentence":"Is there anywhere wash our hands near this stall?","mark":"cross","wrong":"anywhere wash","fix":"anywhere to wash","correct_sentence":"Is there anywhere to wash our hands near this stall?","reason":"Anywhere 後用 to wash 表用途。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (24,'{"number":24,"sentence":"Could someone help us carry these boxes, please?","mark":"tick","wrong":"","fix":"","correct_sentence":"Could someone help us carry these boxes, please?","reason":"請求幫忙的問句可用 someone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (25,'{"number":25,"sentence":"Yesterday, anyone brought a homemade cake to the fair.","mark":"cross","wrong":"anyone","fix":"someone","correct_sentence":"Yesterday, someone brought a homemade cake to the fair.","reason":"說昨天確實有人帶蛋糕，普通用 someone。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (26,'{"number":26,"sentence":"If anyone needs a receipt, please ask at the counter.","mark":"tick","wrong":"","fix":"","correct_sentence":"If anyone needs a receipt, please ask at the counter.","reason":"If anyone 表示若有人需要收據。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (27,'{"number":27,"sentence":"Hardly anyone noticed that the music had stopped.","mark":"tick","wrong":"","fix":"","correct_sentence":"Hardly anyone noticed that the music had stopped.","reason":"Hardly anyone 表示幾乎沒有人留意。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (28,'{"number":28,"sentence":"The volunteers left without telling nobody about the delay.","mark":"cross","wrong":"without telling nobody","fix":"without telling anybody","correct_sentence":"The volunteers left without telling anybody about the delay.","reason":"Without 已含否定意思，普通用 anybody。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (29,'{"number":29,"sentence":"Didn''t you bring something for the lucky draw? I saw you carrying a parcel.","mark":"tick","wrong":"","fix":"","correct_sentence":"Didn''t you bring something for the lucky draw? I saw you carrying a parcel.","reason":"說話者見到包裹，有理由預期對方帶了東西。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (30,'{"number":30,"sentence":"Didn''t you bring anything at all? The table is completely empty.","mark":"tick","wrong":"","fix":"","correct_sentence":"Didn''t you bring anything at all? The table is completely empty.","reason":"Anything at all 強調「真的一點也沒帶嗎」。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (31,'{"number":31,"sentence":"Nobody didn''t want to miss the final performance.","mark":"cross","wrong":"Nobody didn''t want","fix":"Nobody wanted","correct_sentence":"Nobody wanted to miss the final performance.","reason":"Nobody 已帶否定，普通意思不再加 didn''t。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (32,'{"number":32,"sentence":"I didn''t like something in the soup, but I enjoyed the rest.","mark":"tick","wrong":"","fix":"","correct_sentence":"I didn''t like something in the soup, but I enjoyed the rest.","reason":"Didn''t like something 可以只否定湯中某一項，後半句證實並非全盤不喜歡。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (33,'{"number":33,"sentence":"I didn''t buy anything after lunch because I had no money left.","mark":"tick","wrong":"","fix":"","correct_sentence":"I didn''t buy anything after lunch because I had no money left.","reason":"Didn''t buy anything 表示完全沒有購買。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (34,'{"number":34,"sentence":"Everyone can take whichever leaflet they prefer, even if they are not a club member.","mark":"tick","wrong":"","fix":"","correct_sentence":"Everyone can take whichever leaflet they prefer, even if they are not a club member.","reason":"Everyone can 指所有相關人員均可拿傳單；they 回指個別人。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (35,'{"number":35,"sentence":"Nothing was more popular than the students'' chocolate biscuits.","mark":"tick","wrong":"","fix":"","correct_sentence":"Nothing was more popular than the students'' chocolate biscuits.","reason":"Nothing was more popular 表示朱古力餅乾最受歡迎。"}'::jsonb) on conflict(number) do update set data=excluded.data;
insert into error_identifier_private.indefinite_pronouns_key(number,data) values (36,'{"number":36,"sentence":"There was nowhere better to sit than under the large tree.","mark":"tick","wrong":"","fix":"","correct_sentence":"There was nowhere better to sit than under the large tree.","reason":"Nowhere better 指沒有更好的座位。"}'::jsonb) on conflict(number) do update set data=excluded.data;
