-- Individually reviewed reference answers for the student-only indefinite-pronouns sources.
-- The source files did not supply answer keys. Keep these rows off public site assets.
create table if not exists grammar_admin_private.indefinite_pronouns_key (number integer primary key check (number between 1 and 250), data jsonb not null);
create table if not exists error_identifier_private.indefinite_pronouns_key (number integer primary key check (number between 1 and 200), data jsonb not null);
revoke all on grammar_admin_private.indefinite_pronouns_key,error_identifier_private.indefinite_pronouns_key from public,anon,authenticated;
create or replace function grammar_admin_private.indefinite_pronouns_answers(p_token uuid) returns jsonb language plpgsql stable security definer set search_path='' as $function$
begin
 if auth.uid() is null or not exists(select 1 from grammar_admin_private.profile(p_token)) then raise exception 'Admin session expired' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(data order by number) from grammar_admin_private.indefinite_pronouns_key),'[]'::jsonb);
end $function$;
create or replace function public.grammar_admin_indefinite_pronouns_answers(p_token uuid) returns jsonb language sql stable security invoker set search_path='' as $function$ select grammar_admin_private.indefinite_pronouns_answers(p_token) $function$;
revoke all on function grammar_admin_private.indefinite_pronouns_answers(uuid),public.grammar_admin_indefinite_pronouns_answers(uuid) from public,anon;
grant execute on function grammar_admin_private.indefinite_pronouns_answers(uuid),public.grammar_admin_indefinite_pronouns_answers(uuid) to authenticated;
create or replace function error_identifier_private.error_identifier_admin_answers(p_token uuid,p_logout boolean default false) returns jsonb language plpgsql security definer set search_path='' as $function$
begin
 if auth.uid() is null or not exists(select 1 from public.error_identifier_admin_sessions where token=p_token and auth_id=auth.uid() and expires_at>now()) then raise exception 'Admin session expired' using errcode='42501'; end if;
 if p_logout then delete from public.error_identifier_admin_sessions where token=p_token; return '{}'::jsonb; end if;
 return jsonb_build_object('single',(select jsonb_agg(to_jsonb(k) order by question_no) from public.error_identifier_answer_key k),'passages',(select jsonb_agg(to_jsonb(k) order by passage_id,line_no) from public.error_identifier_passage_answer_key k),'jayden',(select jsonb_agg(data order by number) from public.error_identifier_jayden_key),'indefinite',(select jsonb_agg(data order by number) from error_identifier_private.indefinite_pronouns_key));
end $function$;
revoke all on function error_identifier_private.error_identifier_admin_answers(uuid,boolean) from public,anon;
grant execute on function error_identifier_private.error_identifier_admin_answers(uuid,boolean) to authenticated;

